export const saveEncryptedPdf = async (doc: jsPDF, fileName: string, password?: string) => {
  if (password) {
    const pdfBytes = doc.output('arraybuffer');
    const pdfDoc = await PDFDocument.load(pdfBytes);
    const encryptedPdfBytes = await pdfDoc.save({ userPassword: password } as any);
    const blob = new Blob([encryptedPdfBytes.buffer.slice(0) as ArrayBuffer], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    link.click();
    URL.revokeObjectURL(url);
  } else {
    doc.save(fileName);
  }
};

const generateProfessionalPDF = async (title: string, rangeInfo: string, tableHead: string[][], tableBody: any[][], fileName: string, headerColor: [number, number, number], password?: string) => {
  const doc = new jsPDF();
  const businessName = localStorage.getItem('business_name') || 'NEPAL VENTURES GLOBAL';
  const timestamp = new Date().toLocaleString();

  doc.setFillColor(...headerColor);
  doc.rect(14, 15, 10, 10, 'F');
  doc.setFontSize(16);
  doc.setTextColor(255, 255, 255);
  doc.setFont('helvetica', 'bold');
  doc.text('N', 16, 22);

  doc.setFontSize(22);
  doc.setTextColor(20, 20, 20);
  doc.text('PROJECT N', 28, 22);

  doc.setFontSize(10);
  doc.setTextColor(150, 150, 150);
  doc.setFont('helvetica', 'normal');
  doc.text('NEURAL FINANCE ECOSYSTEM', 28, 27);

  doc.setDrawColor(200, 200, 200);
  doc.line(14, 32, 196, 32);

  doc.setFontSize(16);
  doc.setTextColor(0, 0, 0);
  doc.setFont('helvetica', 'bold');
  doc.text(title, 14, 42);
  
  doc.setFontSize(10);
  doc.setTextColor(80, 80, 80);
  doc.setFont('helvetica', 'normal');
  doc.text(`Entity: ${businessName}`, 14, 48);
  doc.text(`Period: ${rangeInfo}`, 14, 53);

  autoTable(doc, {
    startY: 60,
    head: tableHead,
    body: tableBody,
    theme: 'grid',
    headStyles: { fillColor: headerColor, textColor: [255, 255, 255], fontStyle: 'bold' },
    styles: { font: 'helvetica', fontSize: 9, cellPadding: 4 },
    alternateRowStyles: { fillColor: [250, 250, 250] },
    margin: { bottom: 30 },
    columnStyles: { 2: { halign: 'right' } }
  });

  const pageCount = (doc as any).internal.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150, 150, 150);
    const footerText = `Generated by Project N Analysis AI on ${timestamp}  |  Page ${i} of ${pageCount}`;
    doc.text(footerText, 14, doc.internal.pageSize.height - 15);
  }

  await saveEncryptedPdf(doc, fileName, password);
};

